// methodology.html, generated by build.js. renderMethodology({ doc }) returns the page's title,
// description and body; build.js wraps the body in the shared shell (head, CSP, CSS, fonts).
//
// The page is built from the app's own constants and rules (RULES, HONESTY, STATE_INFO,
// SOURCE_INFO, NADAC_EXPLANATION_CODES) and from data/drugs.json (sources, counts, and the
// coverage computed by analyzeDoc() in quality.js with the core rules). Every interpolated value
// goes through esc() by way of the html`` template below; only fragments built by html`` itself
// are inserted unescaped. No inline style attributes, no scripts, no clock.

import { esc } from '../core/esc.js';
import { PRICE_STATES, STATE_INFO } from '../core/provenance.js';
import { RULES, HONESTY, PART_B_SETTING_NOTE, PART_D_BLANK_FLAG_NOTE, EXTREME_HIGH, EXTREME_LOW, EXTREME_HEADLINE, summarizeProduct, defaultQuantity, formatSpreadMultiple } from '../core/rules.js';
import { SOURCE_INFO, NADAC_EXPLANATION_CODES, NADAC_CARRIED_FORWARD_CODES } from '../core/sources.js';
import { REPO_URL, APP_NAME } from '../core/config.js';
import { issueUrl } from '../core/report.js';
import { formatCount, formatMoney, formatUnitPrice } from '../core/money.js';
import { parsePeriod } from '../core/dates.js';
import { analyzeDoc, pct, plural, countText, SHA_PREFIX, PART_D_UNMATCHED_REASONS, PART_B_UNMATCHED_REASONS, PART_B_RECONCILED_BY } from './quality.js';

/** Top-level sections of methodology.html, in order: [id, heading]. The ids are stable anchors. */
export const SECTIONS = Object.freeze([
  Object.freeze(['what-it-shows', 'What OpenBill shows']),
  Object.freeze(['reading-a-card', 'How to read a card']),
  Object.freeze(['rules', 'The rules']),
  Object.freeze(['honesty', 'How prices are presented']),
  Object.freeze(['sources', 'Sources']),
  Object.freeze(['joins', 'How the files are joined']),
  Object.freeze(['explanation-codes', 'NADAC explanation codes']),
  Object.freeze(['limitations', 'Known limitations']),
  Object.freeze(['reproduce', 'Reproduce it']),
  Object.freeze(['report', 'Report a wrong number']),
]);

/** Products tried, in order, for the worked example; else the first product with a spread. */
const EXAMPLE_PRODUCTS = Object.freeze(['ELIQUIS 5 MG TABLET', 'METFORMIN HCL 500 MG TABLET']);

/**
 * The oldest browsers that can unpack the page's inline data: it is deflate-raw compressed, and
 * the page inflates it with DecompressionStream('deflate-raw') (build.js, src/app/app.js).
 */
export const BROWSER_FLOOR = Object.freeze([
  Object.freeze(['Chrome', '103']),
  Object.freeze(['Edge', '103']),
  Object.freeze(['Firefox', '113']),
  Object.freeze(['Safari', '16.4']),
]);

const CADENCE_TEXT = Object.freeze({ daily: 'every day', weekly: 'every week', quarterly: 'every quarter', annual: 'once a year' });
const AGE_FROM_TEXT = Object.freeze({
  as_of_date: 'counted from the file date',
  period_start: 'counted from the first day of the quarter',
  period_end: 'counted from the last day of the data year',
});

// ---------------------------------------------------------------- tiny HTML builder

class Html {
  constructor(s) {
    this.s = s;
  }
  toString() {
    return this.s;
  }
}

function part(v) {
  if (v instanceof Html) return v.s;
  if (Array.isArray(v)) return v.map(part).join('');
  if (v === null || v === undefined || v === false) return '';
  return esc(v);
}

/** Template tag: interpolations are escaped with esc(), except fragments made by html`` itself. */
function html(strings, ...values) {
  let out = strings[0];
  values.forEach((v, i) => {
    out += part(v) + strings[i + 1];
  });
  return new Html(out);
}

/** Text with a line-break opportunity after - _ . / so long file names fit a 360px screen. */
function breakable(text) {
  return new Html(
    String(text)
      .split(/(?<=[-_./])/)
      .map((chunk) => esc(chunk))
      .join('<wbr>'),
  );
}

function checkHref(href) {
  const h = String(href);
  if (!/^(https:\/\/|#|[a-z0-9][a-z0-9._/-]*(#[a-z0-9-]+)?$)/i.test(h)) throw new Error(`methodology: refusing link ${JSON.stringify(h)}`);
  return h;
}

function link(href, text) {
  return html`<a href="${checkHref(href)}">${text}</a>`;
}

function hostOf(url) {
  const m = /^https:\/\/([^/?#]+)/.exec(String(url));
  return m ? m[1] : String(url);
}

function repoDoc(path, anchor) {
  return `${REPO_URL}/blob/main/${path}${anchor ? `#${anchor}` : ''}`;
}

function periodText(period) {
  const p = parsePeriod(period);
  return p ? `${p.start} to ${p.end}` : null;
}

function usdText(rec) {
  return `${formatUnitPrice(rec.value)}${rec.per ? ` per ${rec.per}` : ''}`;
}

function rangeText(range, fmt) {
  if (range.same || range.units.length > 1) return fmt(range.min);
  return `${fmt(range.min)} to ${fmt(range.max)}`;
}

/** A state label, styled like the card's chips (.chip in src/app/styles.css). */
function chip(state) {
  const label = STATE_INFO[state] ? STATE_INFO[state].label : state;
  return html`<span class="chip chip-${state}">${label}</span>`;
}

function provenance(rec) {
  const period = periodText(rec.period);
  return html`${chip(rec.state)} <span class="mono">${rec.source_name} · ${breakable(rec.source_file)} · ${
    period ? `${period}` : `effective ${rec.effective_date}`
  } · retrieved ${rec.retrieved_date}</span>`;
}

function sortedEntries(map) {
  return Object.entries(map && typeof map === 'object' ? map : {}).sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
}

function reasonTable(map, descriptions, rows, caption) {
  const entries = sortedEntries(map);
  if (entries.length === 0) return html`<p>None recorded.</p>`;
  return html`<table class="reasons">
<caption>${caption}</caption>
<thead><tr><th scope="col">Why</th><th scope="col">Rows</th><th scope="col">Share</th></tr></thead>
<tbody>
${entries.map(
  ([k, n]) =>
    html`<tr><td>${Object.prototype.hasOwnProperty.call(descriptions, k) ? descriptions[k] : `${k} (not yet described on this page)`}</td><td>${countText(n)}</td><td>${
      Number.isFinite(n) ? pct(n, rows) : 'n/a'
    }</td></tr>
`,
)}</tbody>
</table>`;
}

// ---------------------------------------------------------------- sections

function section(id, heading, body) {
  return html`<section id="${id}">
<h2>${heading}</h2>
${body}
</section>
`;
}

function whatItShows(a, doc) {
  const partd = doc.sources.partd || {};
  return html`<p>Search for a drug and ${APP_NAME} shows, for each product:</p>
<ul>
<li><strong>What pharmacies pay.</strong> ${SOURCE_INFO.nadac.measures} The figure is CMS’s NADAC (National Average Drug Acquisition Cost).</li>
<li><strong>A Medicare price for the same drug.</strong> What Medicare Part D spent per unit in its latest data year${
    partd.data_year ? ` (${partd.data_year} in this build)` : ''
  }, or else the Medicare Part B payment limit for the current quarter, converted to the same unit. ${link('#reference-price', 'Which one is used')} is a rule below.</li>
<li><strong>The spread.</strong> The Medicare price divided by what pharmacies pay, stated as a multiple in one plain sentence.</li>
</ul>
<p>Every one of those numbers carries its state, the file it came from and its dates.</p>
<p>What it does not show:</p>
<ul>
<li><strong>Your price.</strong> NADAC is what pharmacies pay their suppliers, not what a patient pays at the counter. Medicare’s figures are what Medicare paid or pays. What you pay depends on your pharmacy, your insurance, your deductible and the quantity you are given.</li>
<li><strong>A quote.</strong> A price here is a range to expect, read from government files that each have their own date.</li>
<li><strong>Cash prices, pharmacy list prices or insurers’ prices.</strong> None of the files used so far publishes them, so ${APP_NAME} does not show them yet.</li>
<li><strong>Medical advice.</strong> Nothing here says which drug to take or where to buy it.</li>
</ul>
<p>There is no warranty. The figures come from other people’s data, which can be wrong, and from rules that can have mistakes. If you find a wrong number, ${link('#report', 'tell us')}.</p>`;
}

function example(a) {
  const byName = new Map(a.productList.map((p) => [p.name, p]));
  const candidates = [...EXAMPLE_PRODUCTS.map((n) => byName.get(n)).filter(Boolean), ...a.productList];
  for (const p of candidates) {
    const dq = defaultQuantity(p.rows);
    const s = summarizeProduct(p.rows, dq.qty);
    if (s.reference.missing || s.spread.missing || s.pack.missing || s.pack.min.missing || s.nadac.units.length !== 1 || s.reference.range.units.length !== 1) continue;
    const pack = s.pack.same ? formatMoney(s.pack.min.value) : `${formatMoney(s.pack.min.value)} to ${formatMoney(s.pack.max.value)}`;
    return html`<h3 id="example">An example from this build</h3>
<p>${s.name}, ${plural(s.counts.rows, 'NDC')}:</p>
<dl class="example">
<dt>What pharmacies pay</dt>
<dd>${rangeText(s.nadac, usdText)} ${provenance(s.nadac.min)}</dd>
<dt>For ${formatCount(dq.qty)} ${dq.unit || ''}</dt>
<dd>${pack} ${chip(s.pack.min.state)} (the state of the price it multiplies: ${link('#unit-total', 'pack total')})</dd>
<dt>${s.reference.label}</dt>
<dd>${rangeText(s.reference.range, usdText)} ${provenance(s.reference.range.min)}</dd>
<dt>The spread</dt>
<dd>${s.spread.sentence} ${chip(s.spread.state)} (${link('#spread', 'why it is estimated or derived')})</dd>
</dl>`;
  }
  return html``;
}

function readingACard(a, doc) {
  const recordStates = PRICE_STATES.filter((st) => a.recordsByState[st] > 0);
  const allOne = recordStates.length === 1;
  const sp = a.spreads;
  const spreadTotal = PRICE_STATES.reduce((n, st) => n + (sp.part_d[st] || 0) + (sp.part_b[st] || 0), 0);
  const derived = (sp.part_d.derived || 0) + (sp.part_b.derived || 0);
  const estimated = (sp.part_d.estimated || 0) + (sp.part_b.estimated || 0);
  return html`<p>A card is one product: every NDC (the 11-digit National Drug Code printed on the package) that NADAC lists under the same description. This build has ${plural(
    a.products,
    'product',
  )} made of ${plural(a.rows, 'NDC')}.</p>
<p>Every number on a card has a state label and a provenance line, always visible: the source, the file it was read from, the date it applies from (the effective date) and the date ${APP_NAME} downloaded the file (retrieved). A figure that covers a period, such as a Part D data year or a Part B quarter, shows the period; its effective date is the first day of that period. A figure ${APP_NAME} calculates from others, such as a spread, shows each input’s own date or period beside it (for example “NADAC eff. 2026-09-23 · Part D 2024-01-01 to 2024-12-31”), never only the oldest. The provenance panel, opened from the card, adds the reason for the state, the NADAC explanation codes, the NDCs and the formula.</p>
<p>When a figure is missing the card says “We don’t know yet” and why. It never shows a zero instead. When a source is older than its limit (${link('#freshness', 'freshness')}), the card labels it stale and still shows it.</p>
<h3 id="states">The four states</h3>
<p>Strongest first:</p>
<dl class="states">
${PRICE_STATES.map(
  (st) => html`<dt id="state-${st}">${chip(st)}</dt>
<dd>${STATE_INFO[st].summary}</dd>
`,
)}</dl>
<p>${
    allOne
      ? `In this build all ${formatCount(a.records)} records in data/drugs.json are ${recordStates[0]}: each is a number printed in a government file.`
      : `In this build the ${formatCount(a.records)} records in data/drugs.json are ${PRICE_STATES.map((st) => `${formatCount(a.recordsByState[st] || 0)} ${st}`).join(', ')}.`
  } The numbers the page calculates from them, such as a Part B price per NADAC unit or a spread, are derived or estimated: of the ${formatCount(
    spreadTotal,
  )} spreads on cards, ${formatCount(derived)} are derived and ${formatCount(estimated)} estimated, for the reasons in ${link(
    '#rules',
    'the rules',
  )}. A pack total is the exception: multiplying a price by your quantity is arithmetic, so the total keeps the state of the price it multiplies.</p>
${example(a)}`;
}

function rules() {
  return html`<p>These are the rules in src/core/rules.js, in the words the page uses. Every number ${APP_NAME} calculates links to its rule here.</p>
${RULES.map(
  (r) => html`<section id="${r.id}" class="rule">
<h3>${r.title}</h3>
<p>${r.description}</p>
<p class="formula">Formula: <code>${r.formula}</code></p>
${
  r.id === 'reference-price'
    ? html`<p>What the provenance panel says with every Part B figure: “${PART_B_SETTING_NOTE}”</p>
<p>And with a Part D figure whose outlier flag is blank: “${PART_D_BLANK_FLAG_NOTE}”</p>
`
    : r.id === 'extreme-gap'
    ? html`<p>The thresholds are tested on the ratio at full precision, before it is rounded for display. A ratio of 0.2046 is above ${EXTREME_LOW}, so it carries no warning and keeps its sentence, and the card shows it as ${formatSpreadMultiple(0.2046)}: near a threshold the multiple gets the digits that keep it from reading as the threshold itself.</p>
`
    : ''
}</section>
`,
)}`;
}

function honesty() {
  return html`<p>${APP_NAME} holds every screen to these five rules, word for word:</p>
<ul class="honesty">
${HONESTY.map((h) => html`<li id="honesty-${h.id}">${h.parts.map((p) => (p.strong ? html`<strong>${p.text}</strong>` : p.text))}</li>
`)}</ul>`;
}

function sourceTable(id, entry) {
  const info = SOURCE_INFO[id];
  const rows = [];
  const add = (label, value) => rows.push(html`<tr><th scope="row">${label}</th><td>${value}</td></tr>
`);
  add('Dataset', entry.title || 'not recorded');
  add('Published by', (info && info.publisher) || entry.publisher || 'not recorded');
  if (info && entry.publisher && entry.publisher !== info.publisher) add('Publisher in the file’s metadata', entry.publisher);
  add('Dataset page', entry.source_url ? link(entry.source_url, hostOf(entry.source_url)) : html`<strong>missing</strong>`);
  add(
    'File',
    html`${breakable(entry.source_file || 'not recorded')}${typeof entry.bytes === 'number' ? ` (${plural(entry.bytes, 'byte')})` : ''}${
      entry.member ? html`; read from ${breakable(entry.member)}` : ''
    }`,
  );
  add('sha256', typeof entry.sha256 === 'string' ? html`<code>${entry.sha256.slice(0, SHA_PREFIX)}…</code>` : 'not recorded');
  add('Period', periodText(entry.period) || 'none: not period data');
  add('File date (as of)', entry.as_of_date || 'not recorded');
  add('Retrieved (UTC)', entry.retrieved_date || 'not recorded');
  if (info) {
    add('New file', CADENCE_TEXT[info.cadence] || info.cadence);
    add('Stale after', `${plural(info.stale_after_days, 'day')}, ${AGE_FROM_TEXT[info.age_from] || info.age_from}. ${info.stale_note}`);
  }
  add('Licence', entry.license ? link(entry.license, breakable(entry.license.replace(/^https:\/\//, ''))) : 'not recorded');
  if (typeof entry.weeks_in_file === 'number') add('Weekly files in the download', `${formatCount(entry.weeks_in_file)}; ${APP_NAME} uses the newest`);
  if (typeof entry.products === 'number' && typeof entry.packages === 'number') {
    add('Directory size', `${plural(entry.products, 'product')}, ${plural(entry.packages, 'package')}`);
  }
  if (entry.methodology_url || entry.data_dictionary_url) {
    add(
      'CMS documentation',
      html`${entry.methodology_url ? link(entry.methodology_url, 'methodology') : ''}${entry.methodology_url && entry.data_dictionary_url ? ', ' : ''}${
        entry.data_dictionary_url ? link(entry.data_dictionary_url, 'data dictionary') : ''
      }`,
    );
  }
  return html`<section id="source-${id}" class="source">
<h3>${info ? info.label : id}</h3>
${info ? html`<p>${info.measures}</p>
` : html`<p><strong>This source has no entry in SOURCE_INFO.</strong></p>
`}<table class="source-facts">
<tbody>
${rows}</tbody>
</table>
</section>
`;
}

function sources(doc) {
  return html`<p>Every number comes from one of these files. data/drugs.json records each file’s sha256, so you can check that you have the same bytes. The licences and terms, the fields read and the caveats of each file are in ${link(
    repoDoc('docs/DATA_SOURCES.md'),
    'DATA_SOURCES.md',
  )}.</p>
${Object.keys(doc.sources).map((id) => sourceTable(id, doc.sources[id]))}`;
}

function joins(a, doc) {
  const c = doc.counts || {};
  const n = a.rows;
  const basis = c.part_d_by_basis || {};
  const variantsMerged = a.labelerVariants.filter((v) => v.distinct === 1).length;
  const sp = a.spreads;
  return html`<p>The NADAC file is the spine: one row per NDC in its newest week, ${plural(n, 'row')} in this build. The other files are joined to it on exact keys. A join that is not certain is left empty rather than guessed; each empty join is counted below and explained on the card.</p>
<h3 id="join-identity">Identity: the FDA NDC Directory</h3>
<p>Each NDC is looked up, digit for digit, in the FDA NDC Directory’s package list. FDA writes package NDCs with hyphens in three layouts (4-4-2, 5-3-2 and 5-4-1); the short segment is padded with a zero to make the 11 digits NADAC uses. A match gives the brand and generic names, dosage form, route, strength, labeler and package description.</p>
<p>${formatCount(a.identity)} of ${plural(n, 'row')} (${pct(a.identity, n)}) match. The other ${plural(
    n - a.identity,
    'row',
  )} have no identity: their NDC is not in the directory’s package list (discontinued products leave it, for example), its package has no product record, or its FDA entries conflict with each other (${plural(
    c.identity_ambiguous,
    'NDC',
  )} in this build).</p>
${
  c.part_d_fda_by_product_code && typeof c.part_d_fda_by_product_code === 'object'
    ? html`<p>For the Part D name join only, a row with no identity can be matched using FDA’s record for its 9-digit product code, when that code has one product record and a sibling NDC of the same description is in the directory, or the NADAC description begins with FDA’s trade name or prints its name and strength. That record is not an identity: the row’s identity stays empty and the record never supplies a route. In this build it was tried for ${plural(
        c.part_d_fda_by_product_code.rows,
        'row',
      )}, and ${formatCount(c.part_d_fda_by_product_code.matched)} of them joined a Part D name.</p>
`
    : ''
}<h3 id="join-part-d">Medicare Part D: by name</h3>
<p>Part D Spending by Drug has no NDCs. CMS lists each drug by brand name and generic name, with every strength and form together, so this join is by name: the NADAC description and, when the NDC has an FDA identity, FDA’s brand and generic names, against the names CMS uses. It is strict on purpose. A row gets no Part D figure when:</p>
<ul>
<li>the release forms differ: markers such as ER, XR or DR must be the same on both sides, and FDA’s dosage form must agree;</li>
<li>more than one Part D row could match;</li>
<li>the generic names disagree: the substances must be the same, and so must the salt where both names state one (a hydrate that is the only qualifier counts as the salt);</li>
<li>a brand product has no Part D row with its own brand name;</li>
<li>Part D lists the substance under several salts, or lists several presentations such as pens and vials, and neither the NADAC description nor FDA’s names say which one this NDC is;</li>
<li>a combination product’s NADAC name lists a different number of ingredients from the Part D generic name;</li>
<li>the product is sold over the counter under an FDA OTC monograph, or matches only a Part D row named by the generic name: Part D excludes over-the-counter drugs, so those Part D rows are a different, prescription product;</li>
<li>NADAC prices the NDCs joined to one Part D name in different units and this NDC’s unit is not the one nearly all of them share, because CMS’s average would then mix tablets with milliliters;</li>
<li id="multi-route">the Part D name carries CMS’s *, which marks one average over several routes of administration (tablets and injections, say), and this NDC is not on the route the name’s rows share. A row joins such a name only when it has an FDA identity and its FDA route includes the route that covers the most of the name’s rows, so every row that keeps the figure shares one route. A row with no FDA identity, or on another route, is left out; if two routes cover as many rows but not the same rows, every row is left out. Routes are FDA’s own words, so PARENTERAL is not merged with INTRAVENOUS.</li>
</ul>
<p>${formatCount(a.partD)} of ${plural(n, 'row')} (${pct(a.partD, n)}) match, pointing at ${plural(a.partDNames, 'Part D name')}. For ${plural(
    basis.generic,
    'row',
  )} CMS’s brand name is the generic name itself; for ${plural(basis.brand, 'row')} it is a trade name. The exact rules are in tools/build_drugs.py, and the cases they were written for are in ${link(
    repoDoc('docs/DATA_SOURCES.md', 'partd--medicare-part-d-spending-by-drug'),
    'DATA_SOURCES.md',
  )}.</p>
${reasonTable(c.part_d_unmatched, PART_D_UNMATCHED_REASONS, n, 'Rows with no Part D figure, by reason')}
<p>CMS flags ${plural(a.outlierNames, 'Part D name')} as outliers: the average is substantially affected by unusual records. The ${plural(
    a.outlierRows,
    'row',
  )} pointing at them keep the figure in the data but do not use it as the reference price. The flag is blank for ${plural(a.blankFlagNames, 'name')} (${plural(
    a.blankFlagRows,
    'row',
  )}); a blank flag counts as not flagged, and the provenance panel says so in the figure’s reason.</p>
<h3 id="join-part-b">Medicare Part B: by exact NDC</h3>
<p>The CMS NDC-HCPCS crosswalk lists which NDCs are billed to Part B under which HCPCS code, and how many billing units one package holds. An NDC is joined to it digit for digit; an NDC on crosswalk lines that disagree with each other is left out. The HCPCS code then gives the payment limit and the coinsurance percentage from the payment limit file.</p>
<p>To compare a payment limit with NADAC, the package has to be measured in NADAC’s unit. The crosswalk does not say which unit its package size is in, so ${APP_NAME} accepts it only when FDA’s package description for the same NDC gives the same total (milliliters, grams, or a count of tablets, vials and so on) and the crosswalk’s two billing-unit columns agree with each other. A kit that NADAC prices per EA is counted as whole kits. Where the two billing-unit columns disagree, one is used only when FDA’s strength × the package amount ÷ the HCPCS dosage gives exactly that number. Otherwise the package size is shown as the crosswalk prints it, a number with no unit, and the NDC gets no Part B price per NADAC unit.</p>
<p>${formatCount(a.partB)} of ${plural(n, 'row')} (${pct(a.partB, n)}) are on the crosswalk, under ${plural(a.partBCodes, 'HCPCS code')}; ${formatCount(
    a.partBReconciled,
  )} of them (${pct(a.partBReconciled, a.partB)}) have the package unit reconciled and can be converted to a price per NADAC unit${
    c.part_b_unit_reconciled_by && typeof c.part_b_unit_reconciled_by === 'object'
      ? html`: ${sortedEntries(c.part_b_unit_reconciled_by).map(
          ([k, v], i) =>
            html`${i > 0 ? '; ' : ''}${formatCount(v)} because ${
              Object.prototype.hasOwnProperty.call(PART_B_RECONCILED_BY, k) ? PART_B_RECONCILED_BY[k] : `${k} (not yet described on this page)`
            }`,
        )}`
      : ''
  }.</p>
${reasonTable(c.part_b_unmatched, PART_B_UNMATCHED_REASONS, n, 'Rows with no Part B figure, by reason')}
<p>A payment limit is one figure per code. ${formatCount(a.singleLabelerCodes)} of the ${plural(
    a.partBCodes,
    'code',
  )} have a single labeler (the company named on the label) on the crosswalk, and ${plural(a.singleLabelerRows, 'row')} point at them. For the others the limit averages every labeler’s product billed under the code (${link(
    '#part-b-single-labeler',
    'when a Part B spread counts as derived',
  )}). CMS spells some labeler names more than one way on the crosswalk: ${plural(
    a.labelerVariants.length,
    'code',
  )} list one company under names that differ only in capitals, punctuation or a suffix such as Inc or LLC. ${APP_NAME} counts each company once, and the provenance panel quotes every spelling; ${formatCount(variantsMerged)} of ${
    a.labelerVariants.length === 1 ? 'that code have' : 'those codes have'
  } a single labeler only once the spellings are counted together.</p>
<h3 id="coverage">What the cards end up showing</h3>
<p>With these joins and ${link('#reference-price', 'the reference rule')}: ${formatCount(a.refRows.part_d)} rows (${pct(a.refRows.part_d, n)}) have a Part D reference price, ${formatCount(
    a.refRows.part_b,
  )} (${pct(a.refRows.part_b, n)}) a Part B one and ${formatCount(a.refRows.none)} (${pct(a.refRows.none, n)}) none. By product: ${formatCount(a.refProducts.part_d)} Part D, ${formatCount(
    a.refProducts.part_b,
  )} Part B, ${formatCount(a.refProducts.none)} none, of ${formatCount(a.products)}. ${formatCount(
    a.alternates,
  )} rows with a Part D reference also show a Part B figure in the provenance panel.</p>
<p>Every Part D spread is estimated (${formatCount(sp.part_d.estimated || 0)}). Of the Part B spreads, ${formatCount(sp.part_b.derived || 0)} are derived and ${formatCount(
    sp.part_b.estimated || 0,
  )} estimated. ${plural(a.extremeRows.part_d + a.extremeRows.part_b, 'estimated spread')} at or beyond ${EXTREME_HIGH}× or ${EXTREME_LOW}× carry the ${link(
    '#extreme-gap',
    'large-gap warning',
  )}; on those cards the headline is “${EXTREME_HEADLINE}” instead of the spread’s sentence, with the multiple beside it. The full tables are in ${link(
    repoDoc('docs/DATA-QUALITY.md'),
    'DATA-QUALITY.md',
  )}.</p>`;
}

function explanationCodes(a) {
  const codes = Object.keys({ ...NADAC_EXPLANATION_CODES, ...a.explanation }).sort((x, y) => Number(x) - Number(y) || (x < y ? -1 : x > y ? 1 : 0));
  return html`<p>NADAC marks each price with one or more explanation codes. Their meanings below are from the NADAC data dictionary. Codes ${NADAC_CARRIED_FORWARD_CODES.join(
    ' and ',
  )} mean the price was carried forward from an earlier file rather than set by the latest survey; ${APP_NAME} marks those rows and shows every code in the provenance panel.</p>
<table class="codes">
<caption>NADAC explanation codes in this build</caption>
<thead><tr><th scope="col">Code</th><th scope="col">Meaning</th><th scope="col">Rows</th></tr></thead>
<tbody>
${codes.map(
  (k) => html`<tr><td id="code-${k}">${k}</td><td>${
    Object.prototype.hasOwnProperty.call(NADAC_EXPLANATION_CODES, k) ? NADAC_EXPLANATION_CODES[k] : 'not in the NADAC data dictionary'
  }${NADAC_CARRIED_FORWARD_CODES.includes(k) ? ' (carried forward)' : ''}</td><td>${formatCount(a.explanation[k] || 0)}</td></tr>
`,
)}</tbody>
</table>`;
}

function limitations(a, doc) {
  const c = doc.counts || {};
  const n = a.rows;
  const partd = doc.sources.partd || {};
  const period = parsePeriod(partd.period);
  const mixed = c.part_d_unmatched && c.part_d_unmatched.mixed_units;
  const multiLabeler = a.partBCodes - a.singleLabelerCodes;
  return html`<ul class="limitations">
<li id="limit-part-d"><strong>Part D is a yearly average for a whole name.</strong> CMS averages every strength, form and maker sold under one brand and generic name, weighted by claims, for ${
    partd.data_year ? `data year ${partd.data_year}` : 'one data year'
  }${period ? ` (${period.start} to ${period.end})` : ''}. It is gross spending as CMS defines it: ingredient cost, dispensing fees, sales tax and vaccine administration fees, whether the plan or the patient paid them, and before the rebates drug makers pay back, which CMS may not disclose. So it can sit far from the NADAC of one NDC, and prices may have moved since${
    period ? ` ${period.end}` : ''
  }. That is why every Part D spread is estimated. ${plural(c.part_d_multiple_routes, 'row')} point at names CMS marks with *, an average across routes of administration that can have different unit prices. Only NDCs on the route the name’s rows share keep such a figure (${link(
    '#multi-route',
    'the multi-route rule',
  )}), but the average itself still includes the other routes’ spending, so a tablet can be compared with a figure that is mostly injections or gels.</li>
<li id="limit-dosage-unit"><strong>The Part D unit is assumed.</strong> CMS reports spending per dosage unit but does not say which unit each drug uses. ${APP_NAME} takes it to be NADAC’s unit (EA, ML or GM) for the NDCs joined to that name. Where NADAC prices those NDCs in more than one unit, only the NDCs in the unit nearly all of them share get the figure; ${plural(
    mixed,
    'row',
  )} got none for that reason. A spread far from 1× can still mean the units differ, which is why estimated spreads at or beyond ${EXTREME_HIGH}× or ${EXTREME_LOW}× carry a warning.</li>
<li id="limit-part-b"><strong>Part B pays only in some settings.</strong> ${PART_B_SETTING_NOTE} The payment limit file’s own description of each code is in the provenance panel. A code shared by several labelers has one limit averaged across all their products, so a spread against it is estimated (${formatCount(
    multiLabeler,
  )} of the ${plural(a.partBCodes, 'code')} here). Billing units are whole numbers, so a price per unit can be slightly off for odd package sizes.</li>
<li id="limit-carried-forward"><strong>Some NADAC prices are carried forward.</strong> ${formatCount(a.carriedRows)} of ${plural(n, 'row')} (${pct(
    a.carriedRows,
    n,
  )}) carry explanation code ${NADAC_CARRIED_FORWARD_CODES.join(' or ')}: CMS carried the price forward from an earlier file instead of setting it from the latest survey. They are shown with their codes, not dropped.</li>
<li id="limit-recall"><strong>Low recall, by design.</strong> ${formatCount(a.partD)} of ${plural(n, 'row')} (${pct(a.partD, n)}) match a Part D name, and ${formatCount(
    a.refRows.none,
  )} (${pct(a.refRows.none, n)}) have no Medicare price at all. A wrong Medicare price is worse than none, so an uncertain match is left empty and the card says “We don’t know yet”. Brand and generic versions of a drug are separate products, because ${APP_NAME} has no RxNorm identity yet. The ${plural(
    n - a.identity,
    'row',
  )} without an FDA identity have only the NADAC description and, for some, FDA’s record for their product code to match on, and they never join a Part D name marked *.</li>
<li id="limit-nadac"><strong>NADAC is a survey average.</strong> It is what retail community pharmacies paid on average in CMS’s survey. A given pharmacy may pay more or less, and NADAC says nothing about what a patient pays.</li>
<li id="limit-dates"><strong>Dates are UTC calendar dates.</strong> The page counts every age against today’s UTC date, read from the viewer’s device clock, so the time zone never changes an age; near midnight UTC an age can differ by a day from the viewer’s local calendar. A device clock set behind can make a file look dated tomorrow; its age is then shown as 0 days. ${link(
    repoDoc('docs/DATA-QUALITY.md', 'dates'),
    'DATA-QUALITY.md',
  )} gives each source’s age on the day it was retrieved.</li>
<li id="limit-browser"><strong>Older browsers cannot open it.</strong> The page carries its data compressed (deflate-raw, then base64) and unpacks it with the browser’s own DecompressionStream, which reads that format from ${browserFloorText()}. An older browser cannot unpack it; the page then says so in plain words and shows no figures rather than wrong ones.</li>
</ul>`;
}

/** "Chrome 103, Edge 103, Firefox 113 and Safari 16.4" */
function browserFloorText() {
  const items = BROWSER_FLOOR.map(([name, v]) => `${name} ${v}`);
  return `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`;
}

function reproduce(doc) {
  const sources = Object.keys(doc.sources);
  return html`<p>You need Python 3.10 or later (standard library only) and Node 20 or later. From a copy of ${link(
    REPO_URL,
    'the repository',
  )} (on Windows the Python command is usually python rather than python3):</p>
<pre><code>python3 tools/fetch_all.py
python3 tools/build_drugs.py
node build.js
node build.js --check
node --test</code></pre>
<p>fetch_all.py downloads every source into tools/cache/ and records each file’s sha256; with --offline it only checks the files already there. build_drugs.py reads the cache, never the network, and writes data/drugs.json. build.js writes openbill.html, this page and docs/DATA-QUALITY.md. Nothing generated contains a build time, so the same files give the same bytes. build.js --check fails if a generated file is out of date, and node --test runs the unit, data, spot-check, quality and link tests.</p>
<p>Government sites replace their files. To reproduce these exact numbers, your ${plural(sources.length, 'source file')} must have the sha256 values listed under ${link(
    '#sources',
    'sources',
  )}. A newer file gives newer numbers; that is a data refresh, not a mismatch.</p>`;
}

function report() {
  return html`<p>Every card has a “Wrong? Tell us” link. It opens the wrong-price issue form on GitHub with the card’s details filled in. You can also ${link(
    issueUrl({ template: 'wrong-price.yml' }),
    'open the wrong-price form',
  )} yourself.</p>
<p>The most useful report names the source file and the row in it that shows the right value. A receipt or a price from a website is useful context, but it does not show that a government file was read wrong. Please don’t include your own or anyone else’s health information.</p>
<p>How reports are checked and corrected: ${link(repoDoc('CONTRIBUTING.md', 'reporting-a-wrong-price'), 'CONTRIBUTING.md')} and ${link(
    repoDoc('GOVERNANCE.md', 'data-corrections'),
    'GOVERNANCE.md',
  )}.</p>`;
}

function assertUniqueIds(bodyHtml) {
  const seen = new Set();
  for (const m of bodyHtml.matchAll(/\sid="([^"]*)"/g)) {
    if (seen.has(m[1])) throw new Error(`methodology: duplicate id "${m[1]}"`);
    seen.add(m[1]);
  }
  for (const r of RULES) if (!seen.has(r.id)) throw new Error(`methodology: rule ${r.id} has no anchor`);
}

/**
 * The methodology page: { title, description, bodyHtml }. title and description are plain
 * text (escape them where they are inserted); bodyHtml is HTML with every value escaped, no
 * inline styles and no scripts, starting with its own <h1>. Deterministic: the same doc gives
 * the same strings. Throws on a doc that is not schema openbill.drugs/3, or on an anchor id
 * used twice.
 * @param {{ doc: object }} ctx doc is the parsed data/drugs.json
 * @returns {{ title: string, description: string, bodyHtml: string }}
 */
export function renderMethodology(ctx) {
  const doc = ctx && ctx.doc;
  if (!doc || typeof doc !== 'object' || !doc.sources || typeof doc.sources !== 'object') {
    throw new TypeError('renderMethodology needs { doc }: the parsed data/drugs.json');
  }
  const a = analyzeDoc(doc);
  const nadac = doc.sources.nadac || {};
  const bodies = {
    'what-it-shows': whatItShows(a, doc),
    'reading-a-card': readingACard(a, doc),
    rules: rules(),
    honesty: honesty(),
    sources: sources(doc),
    joins: joins(a, doc),
    'explanation-codes': explanationCodes(a),
    limitations: limitations(a, doc),
    reproduce: reproduce(doc),
    report: report(),
  };
  const body = html`<header class="page-head">
<h1>How ${APP_NAME} works out its numbers</h1>
<p class="lead">This page is generated from the rules the ${APP_NAME} page runs (src/core/rules.js) and from data/drugs.json, built from the NADAC file as of ${
    nadac.as_of_date || 'an unknown date'
  }. Every count on it is computed from that file.</p>
<nav class="toc" aria-label="On this page">
<ol>
${SECTIONS.map(([id, heading]) => html`<li>${link(`#${id}`, heading)}</li>
`)}</ol>
</nav>
</header>
${SECTIONS.map(([id, heading]) => section(id, heading, bodies[id]))}`;
  const bodyHtml = body.s;
  assertUniqueIds(bodyHtml);
  return {
    title: `${APP_NAME} methodology`,
    description: `How ${APP_NAME} reads the NADAC, FDA and Medicare files, the rules it applies to them, and their limits.`,
    bodyHtml,
  };
}
